/** The internal **CLDR** date formats cache. */
const cldrDateFormatsCache: Record<string, string> = {};

/** The format pattern mapping from CLDR format to dayJs/momentJs. */
const cldrFormatMapping: Record<string, string> = {
  d: 'D',
  dd: 'DD',
  y: 'YYYY',
  yy: 'YY',
  yyy: 'YYYY',
  yyyy: 'YYYY',
  a: 'a',
  A: 'A',
  M: 'M',
  MM: 'MM',
  MMM: 'MMM',
  MMMM: 'MMMM',
  h: 'h',
  hh: 'hh',
  H: 'H',
  HH: 'HH',
  m: 'm',
  mm: 'mm',
  s: 's',
  ss: 'ss',
  S: 'SSS',
  SS: 'SSS',
  SSS: 'SSS',
  E: 'ddd',
  EE: 'ddd',
  EEE: 'ddd',
  EEEE: 'dddd',
  EEEEE: 'dddd',
  EEEEEE: 'dddd',
  D: 'DDD',
  w: 'W',
  ww: 'WW',
  z: 'ZZ',
  zzzz: 'Z',
  Z: 'ZZ',
  X: 'ZZ',
  XX: 'ZZ',
  XXX: 'Z',
  u: 'E',
};

/** Checks if the substring is a mapped date format pattern and adds it to the result format String. */
const _appendMappedString = function (
  formatString: string,
  mapping: Record<string, string>,
  startIndex: number,
  currentIndex: number,
  resultString: string,
) {
  if (startIndex !== -1) {
    let tempString = formatString.substring(startIndex, currentIndex);

    // check if the temporary string has a known mapping
    const mapped = mapping[tempString];
    if (mapped) {
      tempString = mapped;
    }

    resultString += tempString;
  }

  return resultString;
};

/** Translates the java date format String to a momentJs format String. */
const translateFormat = function (formatString: string, mapping: Record<string, string>) {
  const len = formatString.length;
  let i = 0;
  let startIndex = -1;
  let lastChar: string | null = null;
  let currentChar = '';
  let resultString = '';

  for (; i < len; i++) {
    currentChar = formatString.charAt(i);

    if (lastChar === null || lastChar !== currentChar) {
      // change detected
      resultString = _appendMappedString(formatString, mapping, startIndex, i, resultString);

      startIndex = i;
    }

    lastChar = currentChar;
  }

  return _appendMappedString(formatString, mapping, startIndex, i, resultString);
};

/** Converts a CLDR date format String to a dayJs format string. */
export function cldrToDayJsFormatString(formatString: string) {
  if (!cldrDateFormatsCache[formatString]) {
    let mapped = '';
    // Match CLDR escapes ('...'), Day.js escapes ([...]), regular chunks, or unmatched characters
    const regexp = /('[^']*')|(\[[^\]]*\])|([^'\[]+)|(['\[])/g;
    let part: RegExpExecArray | null;

    while ((part = regexp.exec(formatString))) {
      const partStr = part[0];

      if (partStr.startsWith("'") && partStr.endsWith("'") && partStr.length > 1) {
        // Convert CLDR escape to Day.js escape
        mapped += `[${partStr.substring(1, partStr.length - 1)}]`;
      } else if (partStr.startsWith('[') && partStr.endsWith(']') && partStr.length > 1) {
        // Already a Day.js escape, preserve it
        mapped += partStr;
      } else {
        // Translate normal tokens
        mapped += translateFormat(partStr, cldrFormatMapping);
      }
    }

    cldrDateFormatsCache[formatString] = mapped;
  }

  return cldrDateFormatsCache[formatString];
}
