/* eslint-disable @stencil-community/ban-default-true */
import { Component, Element, EventEmitter, h, Prop, Event, Host, ComponentInterface, State } from '@stencil/core';
import { Status } from '@src/shared/base-props';
import { DetailArgs } from '@src/shared/dom';
import { normalizeTimezoneInfo, TimezoneInfo } from '@src/shared/timezone';
import { Dayjs } from 'dayjs';
import {
  NormalizedDatePickerComparisonProps,
  DatePickerViewMode,
  DatePresetOptions,
  DateValue,
  DatePickerComparisonProps,
  ValueChangeInfo,
  ComparisonChangeInfo,
  DateTimeFormatOptions,
} from '../types';
import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';
import { computed } from '@src/shared/perf/cache';
import { Placement } from '@floating-ui/dom';
import { dateValueToDayjs, getNow } from '../utils';
import { globalConfigStore } from '@src/shared/stores';
import { isEqual } from 'lodash-es';
import { cldrToDayJsFormatString } from '@src/shared/i18n/date-format';

const NOOP_DISABLED_DATE = (): false => false;

/**
 * The DateTimePickerBase component serves two primary purposes:
 * 1. Normalization: It normalizes external prop values into a consistent internal format for use by internal components.
 * 2. Composition: It assembles and orchestrates the various internal components (e.g., Calendar, TimePanel) that constitute the complete date-time picker.
 */
@Component({
  tag: 'ks-date-time-picker-adapter',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDateTimePickerAdapter implements ComponentInterface {
  @Element() el!: HTMLKsDateTimePickerAdapterElement;

  // ══════════════════════════════════════════════════════════════════════════
  //  [➡️ External As-is] External API Props (Pass-through)
  // ══════════════════════════════════════════════════════════════════════════
  // The below props are passed through to the underlying component without any modification.
  // They are part of the public API and are used as-is.
  // Copy them directly to external components like KsDateTimePicker, KsDateRangePicker, KsDateRange.

  /** If true, a clear button is shown when the input has a value and is focused, allowing the user to clear the content. */
  @Prop() clearable = true;
  /** Sets the validation status of the input, affecting its visual style (e.g., 'error', 'warning'). */
  @Prop() status?: Status;
  /** The timezone info. Defaults to the global `timezone` setting of `Keystone.config()`. */ // TODO label 应当允许完全自定义的节点
  @Prop() timezone?: TimezoneInfo;
  /** Whether or not to show the timezone indicator. When `true`, act as `{ placement: 'input' }`. */
  @Prop() showTimezone?: boolean | { placement: 'input' | 'panel'; style?: 'longOffset' | 'full' } = false; // TODO label 应当允许完全自定义的节点
  /** The placement of the popover relative to the picker input. */
  @Prop() placement: Placement = 'bottom-start';
  /** The open state of the selection popup of the picker. */
  @Prop() open?: boolean;
  /** The default open state of the selection popup of the picker. */
  @Prop() defaultOpen = false;
  /** When `true`, the picker will need clicking a confirm button to apply the selection. */
  @Prop() needConfirm = false;
  /** Whether or not to show the cancel button in the popup footer, commonly used when `needConfirm` is `true`. */
  @Prop() showCancel = false;

  /** The anchor date used to navigate the calendar panel view. The panel will display the calendar page (e.g., month, year) that contains this date. */
  @Prop() viewDate?: DateValue;
  /** The `disabledDate` will apply to both date in the selection popup and the presets. */
  @Prop() disabledDate?: (
    date: DateValue,
    info: { type: 'date' | 'preset'; from?: DateValue; to?: DateValue; selectionPhase?: 'start' | 'end' },
  ) => boolean;

  /** Emitted when the clear button is clicked. */
  @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter<void>;
  /** Emitted when the open state changes. Emits the new open state as a boolean. */
  @Event({ bubbles: false, composed: false }) ksOpenChange!: EventEmitter<boolean>;
  /** Emitted when the `viewDate` changes. */
  @Event({ bubbles: false, composed: false }) ksViewDateChange!: EventEmitter<DateValue>;
  /** Emitted when the `viewMode` changes. */
  @Event({ bubbles: false, composed: false }) ksViewModeChange!: EventEmitter<DatePickerViewMode>;

  // @Slot({ slotname: 'footer' }) private footerSlot?: Slots;

  // ══════════════════════════════════════════════════════════════════════════
  //  [↪️ External Adapted] External API Props (Needs Adaptation)
  // ══════════════════════════════════════════════════════════════════════════
  // The below props are part of the public API but require internal normalization or adaptation.
  // Copy them to external components but shrink/adapt their types as needed.
  // e.g. `value` should be `DateValue | null` in DatePicker, but `[Dayjs | null, Dayjs | null]` in DateRangePicker.

  /**
   * The selected value. It can be a single value or a tuple of two values for range selection. When `null`, the field is considered unselected.
   * @note As we have many systems with customized timezone implementations, use **timezone-agnostic** `value` is more accurate and robust.
   */
  @Prop() value?: DateValue | null | [DateValue | null, DateValue | null];
  /** The default selected value, used in uncontrolled mode. */
  @Prop() defaultValue?: DateValue | null | [DateValue | null, DateValue | null] = null;
  /** Placeholder text. When `undefined`, displays the default placeholder text. */
  @Prop() placeholder?: string | undefined | [string | undefined, string | undefined];
  /** If true, the field will be disabled and non-interactive. */
  @Prop() disabled?: boolean | [boolean, boolean];
  /**
   * Configures the Date Picker's comparison feature.
   * To ensure predictable state management for this advanced feature, it operates in a **fully controlled mode**.
   * The parent component is responsible for managing this state and passing it back via props in response to the `onComparisonChange` event.
   */
  @Prop() comparison?: DatePickerComparisonProps;
  /** The view mode of the date picker. e.g. `'dateInMonth'` to display the date grid for selecting a date in a month. */
  @Prop() viewMode?: DatePickerViewMode;
  /** The available view modes of the date picker, they will be navigable with the date grid header. */
  @Prop() availableViewModes: DatePickerViewMode[] = ['dateInMonth', 'monthInYear', 'yearInDecade'];
  /** The format options of the display field */
  @Prop() displayFormatOptions!: DateTimeFormatOptions;
  /**
   * The format of the `value` prop string. Used for parsing the `value` prop.
   * @note As we have many systems with customized timezone implementations, use **timezone-agnostic** `value` is more accurate and robust.
   */
  @Prop() format?: string = 'YYYY-MM-DDTHH:mm:ss';
  /** The presets options of the picker. When `true`, enables with the default preset options. */
  @Prop() presets: boolean | { options: DatePresetOptions } = false;

  /** Emitted when the selected value changes. Emits either a single date value, a range tuple, or `null` when the selection is cleared. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<
    DetailArgs<[DateValue | null | [DateValue | null, DateValue | null], info: ValueChangeInfo]>
  >;
  /** Emitted when interactions in the Date Picker's comparison feature propose an update to `comparison`. */
  @Event({ bubbles: false, composed: false }) ksComparisonChange!: EventEmitter<
    DetailArgs<[DatePickerComparisonProps, info: ComparisonChangeInfo]>
  >;

  // FIXME adapt all
  /** Emitted when the user picks a comparison value. */
  @Prop() onComparisonPick?: (comparison: DatePickerComparisonProps, info: ComparisonChangeInfo) => void;

  // ══════════════════════════════════════════════════════════════════════════
  //  [🛠️ Internal API] Component Config API Passed to KsDateTimePickerAdapter
  // ══════════════════════════════════════════════════════════════════════════
  // Internal props passed from a wrapper component to configure the base component's behavior.
  // Not exposed to the end-user, but needs to be configured and passed down from e.g., DatePicker, DateRangePicker.

  /** If true, the presenter will display two field displays for a range. If false, a single field is displayed. */
  @Prop() isRange!: boolean;
  /** Whether to render a single DateGrid, or dual to have a broader view of selection. @note Unrelated to `isRange`, purely controls view. */
  @Prop() displayMode!: 'single' | 'dual';
  /** When `2-step`, after the user select the start date, they need **click the next button** before select the end date. */
  @Prop() rangeSelectionMode!: 'direct' | '2-step';
  /** The default view mode of the date picker, decides displaying year/month/date selection panel. */
  @Prop() defaultViewMode: DatePickerViewMode = 'dateInMonth';

  // @Prop() private showNow = false;
  // @Prop() private autoFocus = false;

  // ══════════════════════════════════════════════════════════════════════════
  //  [✨ Internal State & Derived] Private state and derived data managed by the adapter
  // ══════════════════════════════════════════════════════════════════════════
  // Private state and derived data fully managed by this adapter component.

  @Uncontrollable('value', 'defaultValue', null) @State() mergedValue?:
    | DateValue
    | null
    | [DateValue | null, DateValue | null];
  @Uncontrollable('open', 'defaultOpen', 'ksOpenChange') @State() mergedOpen?: boolean;
  // eslint-disable-next-line @stencil-community/own-props-must-be-private
  @State() defaultViewDate?: DateValue; // Currently we don't have to expose this prop to external
  @Uncontrollable('viewDate', 'defaultViewDate', 'ksViewDateChange') @State() mergedViewDate?: DateValue;
  @Uncontrollable('viewMode', 'defaultViewMode', 'ksViewModeChange') @State() mergedViewMode!: DatePickerViewMode;

  @Slot({ slotname: 'popupExtraFooter' }) private popupExtraFooterSlot?: Slots;
  @Slot({ slotname: 'popupFooterAppend' }) private popupFooterAppendSlot?: Slots;
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  get mergedTimezone() {
    return normalizeTimezoneInfo(this.timezone, globalConfigStore.state.timezone);
  }

  get normalizedFormat() {
    return cldrToDayJsFormatString(this.format || '');
  }

  private getNow = computed((mergedTimezone: this['mergedTimezone']) => getNow(mergedTimezone));
  private getNormalizedViewDate = computed(
    (
      mergedViewDate: this['mergedViewDate'],
      mergedValue: this['mergedValue'],
      normalizedFormat: this['normalizedFormat'],
      mergedTimezone: this['mergedTimezone'],
    ): Dayjs => {
      const normalizedValue = this.getNormalizedValue(mergedValue, normalizedFormat, mergedTimezone);
      const defaultViewDateInDayjs = mergedValue
        ? normalizedValue[0] || normalizedValue[1] || this.getNow(mergedTimezone)
        : this.getNow(mergedTimezone);
      if (mergedViewDate) {
        return dateValueToDayjs(mergedViewDate, normalizedFormat, mergedTimezone) || defaultViewDateInDayjs;
      } else {
        return defaultViewDateInDayjs;
      }
    },
    { deepEqual: true },
  );

  /** Normalize the value to a tuple of two Dayjs objects to simplify internal operations. */
  private getNormalizedValue = computed(
    (
      mergedValue: this['mergedValue'],
      normalizedFormat: this['normalizedFormat'],
      mergedTimezone: this['mergedTimezone'],
    ): [Dayjs | null, Dayjs | null] => {
      if (this.isRange) {
        if (Array.isArray(mergedValue)) {
          return [
            dateValueToDayjs(mergedValue[0], normalizedFormat, mergedTimezone),
            dateValueToDayjs(mergedValue[1], normalizedFormat, mergedTimezone),
          ];
        } else {
          return [dateValueToDayjs(mergedValue, normalizedFormat, mergedTimezone), null];
        }
      } else {
        return Array.isArray(mergedValue)
          ? [dateValueToDayjs(mergedValue[0], normalizedFormat, mergedTimezone), null]
          : [dateValueToDayjs(mergedValue, normalizedFormat, mergedTimezone) || null, null];
      }
    },
    { deepEqual: true },
  );
  private setValue = (value: [Dayjs | null, Dayjs | null], info: ValueChangeInfo) => {
    const startDateValue = value[0] ? value[0].format(this.normalizedFormat) : null;
    if (this.isRange) {
      const endDateValue = value[1] ? value[1].format(this.normalizedFormat) : null;
      this.mergedValue = [startDateValue, endDateValue];
      this.ksChange.emit(DetailArgs([startDateValue, endDateValue] as [DateValue | null, DateValue | null], info));
    } else {
      this.mergedValue = startDateValue;
      this.ksChange.emit(DetailArgs(startDateValue, info));
    }
  };
  /** Normalize the disabled state to a tuple of two boolean values to simplify internal operations. */
  private getNormalizedDisabled = computed(
    (disabled: this['disabled']): [boolean, boolean] => {
      if (this.isRange) {
        if (Array.isArray(disabled)) {
          return [disabled[0] || false, disabled[1] || false];
        } else {
          return [disabled || false, disabled || false];
        }
      } else {
        return Array.isArray(disabled)
          ? [disabled[0] || false, disabled[0] || false]
          : [disabled || false, disabled || false];
      }
    },
    { deepEqual: true },
  );
  private getNormalizedPlaceholder = computed(
    (placeholder: this['placeholder']): [string | undefined, string | undefined] => {
      if (Array.isArray(placeholder)) {
        return [
          placeholder[0] !== undefined ? placeholder[0] : undefined,
          placeholder[1] !== undefined ? placeholder[1] : undefined,
        ];
      } else {
        const _placeholder: string | undefined = placeholder !== undefined ? placeholder : undefined;
        return [_placeholder, _placeholder];
      }
    },
    { deepEqual: true },
  );
  private getNormalizedShowTimezone = computed(
    (showTimezone: this['showTimezone']): false | { placement: 'input' | 'panel'; style?: 'longOffset' | 'full' } => {
      if (typeof showTimezone === 'object') {
        return showTimezone;
      } else if (showTimezone === true) {
        return { placement: 'input' };
      } else {
        return false;
      }
    },
    { deepEqual: true },
  );
  private getNormalizedDisabledDate = computed(
    (
      disabledDate: this['disabledDate'],
    ): ((
      date: Dayjs,
      info: { type: 'date' | 'preset'; from?: Dayjs; to?: Dayjs; selectionPhase?: 'start' | 'end' },
    ) => boolean) => {
      if (typeof disabledDate === 'function') {
        return (date, info) =>
          disabledDate(date.format(this.normalizedFormat), {
            ...info,
            from: info.from?.format(this.normalizedFormat),
            to: info.to?.format(this.normalizedFormat),
            selectionPhase: info.selectionPhase,
          });
      } else {
        return NOOP_DISABLED_DATE;
      }
    },
    { deepEqual: true },
  );
  private normalizeComparisonValue = (
    comparisonValue: DatePickerComparisonProps['value'],
    normalizedFormat: this['normalizedFormat'],
    timezone: TimezoneInfo,
  ): NormalizedDatePickerComparisonProps['value'] => {
    if (!comparisonValue) {
      return [null, null];
    }
    if (Array.isArray(comparisonValue)) {
      return [
        dateValueToDayjs(comparisonValue[0], normalizedFormat, timezone),
        dateValueToDayjs(comparisonValue[1], normalizedFormat, timezone),
      ];
    } else {
      return [dateValueToDayjs(comparisonValue, normalizedFormat, timezone), null];
    }
  };
  private getNormalizedComparison = computed(
    (
      comparison: this['comparison'],
      normalizedFormat: this['normalizedFormat'],
      mergedTimezone: this['mergedTimezone'],
    ): NormalizedDatePickerComparisonProps => {
      if (!comparison) {
        return { switchable: false, switchDisabled: false, active: false, value: [null, null] };
      }
      return {
        ...comparison,
        switchDisabled: comparison.switchDisabled || false,
        switchable: comparison.switchable ?? true,
        value: this.normalizeComparisonValue(comparison.value, normalizedFormat, mergedTimezone),
      };
    },
    { deepEqual: true },
  );
  private setComparison = (comparison: NormalizedDatePickerComparisonProps, info: ComparisonChangeInfo) => {
    const newComparison: DatePickerComparisonProps = {
      ...comparison,
      value: [
        comparison.value[0]?.format(this.normalizedFormat) || null,
        comparison.value[1]?.format(this.normalizedFormat) || null,
      ],
    };
    if (!isEqual(newComparison, this.comparison)) {
      this.ksComparisonChange.emit(DetailArgs(newComparison, info));
    }
  };
  private handleComparisonPick = (comparison: NormalizedDatePickerComparisonProps, info: ComparisonChangeInfo) => {
    if (!this.onComparisonPick) {
      return;
    }
    const newComparison: DatePickerComparisonProps = {
      ...comparison,
      value: [
        comparison.value[0]?.format(this.normalizedFormat) || null,
        comparison.value[1]?.format(this.normalizedFormat) || null,
      ],
    };
    // Better to compare old and new drafts
    this.onComparisonPick(newComparison, info);
  };

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  private handleViewChange = (viewDate: Dayjs, viewMode: DatePickerViewMode) => {
    this.mergedViewDate = viewDate.format(this.normalizedFormat);
    this.mergedViewMode = viewMode;
  };

  private setOpen = (open: boolean) => {
    this.mergedOpen = open;
    if (!open) {
      this.handleViewChange(
        this.getNormalizedValue(this.mergedValue, this.normalizedFormat, this.mergedTimezone)[0] ||
          this.getNow(this.mergedTimezone),
        this.mergedViewMode,
      );
    }
  };

  private initDefaultViewDate() {
    if (Array.isArray(this.mergedValue)) {
      if (this.mergedValue[0]) {
        this.defaultViewDate = this.mergedValue[0];
      }
    } else if (this.mergedValue) {
      this.defaultViewDate = this.mergedValue;
    }
  }
  connectedCallback() {
    this.initDefaultViewDate();
  }

  render() {
    return (
      <Host>
        <ks-date-time-picker-core
          exportparts="fieldTimezone"
          value={this.getNormalizedValue(this.mergedValue, this.normalizedFormat, this.mergedTimezone)}
          setValue={this.setValue}
          now={this.getNow(this.mergedTimezone)}
          viewDate={this.getNormalizedViewDate(
            this.mergedViewDate,
            this.mergedValue,
            this.normalizedFormat,
            this.mergedTimezone,
          )}
          viewMode={this.mergedViewMode}
          availableViewModes={this.availableViewModes}
          handleViewChange={this.handleViewChange}
          disabled={this.getNormalizedDisabled(this.disabled)}
          open={this.mergedOpen || false}
          setOpen={this.setOpen}
          clearable={this.clearable}
          comparison={this.getNormalizedComparison(this.comparison, this.normalizedFormat, this.mergedTimezone)}
          setComparison={this.setComparison}
          onComparisonPick={this.handleComparisonPick}
          disabledDate={this.getNormalizedDisabledDate(this.disabledDate)}
          displayMode={this.displayMode}
          rangeSelectionMode={this.rangeSelectionMode}
          isRange={this.isRange}
          placeholder={this.getNormalizedPlaceholder(this.placeholder)}
          placement={this.placement}
          presets={this.presets}
          needConfirm={this.needConfirm}
          normalizedFormat={this.normalizedFormat}
          showCancel={this.showCancel}
          status={this.status || 'default'}
          timezone={this.mergedTimezone}
          showTimezone={this.getNormalizedShowTimezone(this.showTimezone)}
          displayFormatOptions={this.displayFormatOptions}
          data-testid="adapter-index-jYhiHP"
        >
          {this.popupExtraFooterSlot && <slot name="popupExtraFooter" slot="popupExtraFooter"></slot>}
          {this.popupFooterAppendSlot && <slot name="popupFooterAppend" slot="popupFooterAppend"></slot>}
          {this.prefixSlot && <slot name="prefix" slot="prefix"></slot>}
        </ks-date-time-picker-core>
      </Host>
    );
  }
}
